def binary(a,start,end,e):
    mid=(start+end)//2
    if a[mid]==e:
        return mid
    elif a[mid]>e:
        end=mid-1
    else:
        start=mid+1
    if start<=end:
        return binary(a,start,end,e)
    else:
        return start
