        if b == 1:
            bob += 1
    return alice >= k and bob >= k

def brute(arr,k):
    result = float('inf')
    for comboSize in range(len(arr)-1, 0, -1):
        for combo in itertools.combinations(arr,comboSize):
            # print(combo)
            if good(combo,k):
                curr = sum(t for t,_,_ in combo)
                if curr < result:
