def sieve():
    li=[True]*1000001
    li[0],li[1]=False,False
    for i in range(2,len(li),1):
        if li[i]==True:
            for j in range(i*i,len(li),i):
                li[j]=False
    prime=[]
    for i in range(1000001):
        if li[i]==True:
            prime.append(i)
    return prime
def setBit(n):
    count=0
    while n!=0:
        n=n&(n-1)
        count+=1
    return count
def readTree(v,e): # to read tree
    adj=[set() for i in range(v+1)]
    for i in range(e):
        u1,u2,w=IP()
        adj[u1].add((u2,w))
        adj[u2].add((u1,w))
    return adj
def dfshelper(adj,i,visited):
    nodes=1
    visited[i]=True
    for ele in adj[i]:
        if visited[ele]==False:
            nd=dfshelper(adj,ele,visited)
            nodes+=nd
    return nodes
def dfs(adj,v): # a schema of bfs
    visited=[False]*(v+1)
    li=[]
    for i in range(v):
        if visited[i]==False:
            nodes=dfshelper(adj,i,visited)
            li.append(nodes)

    return li
