GB, AB, BB, RB = ([] for _ in range(4))

for t, a, b, i in B:
	if a and b: GB.append((t, i))
	elif a: AB.append((t, i))
	elif b: BB.append((t, i))
	else: RB.append((t, i))

N = 1
while N <= 10 ** 4: N *= 2

T = [(0, 0)] * (2 * N)
def comb(a, b): return (a[0] + b[0], a[1] + b[1])

def add_book(t, inc=1):
	i = t + N
	T[i] = comb(T[i], (t*inc, inc))
	while i > 1:
		i //= 2
		T[i] = comb(T[i*2], T[i*2+1])

def query(x):
	assert x >= 0
	s = 0
	i = 1
	while x:
		ts, tc = T[i]
		if tc < x: return INF
		elif tc == x:
			s += ts
			break

		if i >= N:
			s += ts // tc * x
			break

		i *= 2
		if T[i][1] < x:
			s += T[i][0]
			x -= T[i][1]
			i += 1
	return s

