import io
import os


def solve(N, M, K, books):
    A = []
    B = []
    common = []
    padding = SortedList()
    paddingSum = 0
    extras = SortedList()
    for i, (t, a, b) in enumerate(books):
        if a and b:
            common.append(t)
        elif a:
            A.append(t)
        elif b:
            B.append(t)
        else:
            extras.add(t)

    A.sort()
    B.sort()
    common.sort()

    prefA = [0]
    for t in A:
        prefA.append(prefA[-1] + t)
    prefB = [0]
    for t in B:
        prefB.append(prefB[-1] + t)
    prefC = [0]
    for t in common:
        prefC.append(prefC[-1] + t)

    # Check allowable number of common books
    cMin = max(0, K - len(A), K - len(B), 2 * K - M)
    cMax = min(K, len(common))
    if cMin > cMax:
        return -1

    # Want to contain every book in: common[:c], B[: K - c], A[: K - c], padding, extras
    # Starting with c = cMin
    for i in range(cMin, len(common)):
        extras.add(common[i])
    for i in range(K - cMin, len(A)):
        extras.add(A[i])
    for i in range(K - cMin, len(B)):
        extras.add(B[i])

    best = (float("inf"),)
    for c in range(cMin, cMax + 1):
        # Take c common books to satisfy both
        # Need K - c more from A and B each
        assert 0 <= c <= len(common)
        assert 0 <= K - c <= len(A)
        assert 0 <= K - c <= len(B)

        # Pad this up to make M books exactly
        pad = M - c - (K - c) * 2
        assert pad >= 0
        # Fill padding from extras
        while len(padding) < pad and extras:
            x = extras[0]
            extras.remove(x)
            padding.add(x)
            paddingSum += x
        # Overflow padding to extras
        while len(padding) > pad:
            x = padding[-1]
            padding.remove(x)
            paddingSum -= x
            extras.add(x)

        if len(padding) == pad:
            cost = prefC[c] + prefB[K - c] + prefA[K - c] + paddingSum
            best = min(best, (cost, c))
            # print(cost, common[:c], B[: K - c], A[: K - c], padding, extras)
        assert c + (K - c) + (K - c) + len(padding) + len(extras) == N
        if padding and extras:
            assert padding[-1] <= extras[0]
            # assert sum(padding) == paddingSum

        if 0 <= K - c - 1 < len(A):
            x = A[K - c - 1]
            if padding and x <= padding[-1]:
                padding.add(x)
                paddingSum += x
            else:
                extras.add(x)
        if 0 <= K - c - 1 < len(B):
            x = B[K - c - 1]
            if padding and x <= padding[-1]:
                padding.add(x)
                paddingSum += x
            else:
                extras.add(x)
        if c < len(common):
            x = common[c]
            if x in extras:
                extras.remove(x)
            elif x in padding:
                padding.remove(x)
                paddingSum -= x

    if best[0] == float("inf"):
        return -1
    needC = best[1]
    needA = K - needC
    needB = K - needC
    needPad = M - needC - needB - needA

    check = 0
    ans = []
    for i, (t, a, b) in sorted(enumerate(books), key=lambda ix: ix[1][0]):
        if a and b:
            if needC:
                needC -= 1
                ans.append(str(i + 1))
                check += t
                continue
        if a:
            if needA:
                needA -= 1
                ans.append(str(i + 1))
                check += t
                continue
        if b:
            if needB:
                needB -= 1
                ans.append(str(i + 1))
                check += t
                continue
        if needPad:
            needPad -= 1
            ans.append(str(i + 1))
            check += t
    assert len(ans) == M
    assert check == best[0]

    return str(best[0]) + "\n" + " ".join(x for x in ans)


