import unittest
import sys
import re

###############################################################################
# Rebus Class (Main Program)
###############################################################################


class Rebus:
    """ Rebus representation """

    def __init__(self, test_inputs=None):
        """ Default constructor """

        it = iter(test_inputs.split("\n")) if test_inputs else None

        def uinput():
            return next(it) if it else sys.stdin.readline().rstrip()

        # Reading single elements
        self.str = uinput()

        # End value
        self.n = 0
        m = re.search("(\d+)", self.str)
        if m:
            self.n = int(m.group(1))

        # Signs
        self.signs = ["+"] + re.findall("\? ([+-])", self.str)

    def summ(self, nums, signs):
        result = 0
        for i in range(len(self.signs)):
            if self.signs[i] == "+":
                result += nums[i]
            else:
                result -= nums[i]
        return result

    def calculate(self):
        """ Main calcualtion function of the class """

        nums = [0] * len(self.signs)
        for i in range(len(self.signs)):
            nums[i] = 1

        sum = self.summ(nums, self.signs)

        for i in range(len(self.signs)):
            if sum != self.n:
                if self.signs[i] == "+" and sum < self.n:
                    nums[i] = min(self.n - sum + 1, self.n)
                    sum -= 1
                    sum += nums[i]
                if self.signs[i] == "-" and sum > self.n:
                    nums[i] = min(sum + 1 - self.n, self.n)
                    sum += 1
                    sum -= nums[i]

        if sum == self.n:
            result = "Possible\n"

            for i in range(len(self.signs)):
                if i != 0:
                    result += self.signs[i] + " "
                result += str(nums[i]) + " "
            result += "= " + str(self.n)
        else:
            result = "Impossible"

        return str(result)

###############################################################################
# Unit Tests
###############################################################################


class unitTests(unittest.TestCase):

    def test_single_test(self):
        """ Rebus class testing """

        # Constructor test
        test = "? + ? - ? + ? + ? = 42"
        d = Rebus(test)
