def mem_alloc(n, a, mem):
    first, last = 0, 0
    free_list= []
    counting = False
    for i in range(len(mem)):
        if counting:
            if mem[i] != 0:
                last = i - 1
                free_list.append((first, last))
                counting = False
            else:
                last = i
        elif mem[i] == 0:
            first = i
            last = i
            counting = True
    if counting:
        free_list.append((first, last))
    for block in free_list:
        if n <= (block[1] - block[0] + 1):
            for j in range(block[0], block[0] + n):
                mem[j] = a
            return True
    return False

