def gcd(a,b):
    if b==0:
        return a
    else:
        return gcd(b,a%b)


def solve(r,lcm,b):

    no_of_term=r//lcm
    product=no_of_term*lcm

    tot=r

    if product!=0:

        tot-=min(b,(r-product+1))
        tot-=(no_of_term-1)*b

    return tot-min(r,b-1)

for _ in range(int(input())):

