import math

def factoriation(n):
    k=int(math.sqrt(n))+1

    l=[0]*k

    t=0
    l[0]=0
    l[1]=0


    while n%2==0:
        t+=1
        n=n//2

    l[2]=t

    for i in range(3,k):
        t=0
        while n%i==0:
            t+=1
            n=n//i
        l[i]=t

        if n==1:
            return l
        else:
            return [0,0,0,0]

    return l

