import math

def factor(n,a):

    l=[]
    r=n
    k=int(math.sqrt(n))+1

    d=1

    while n%(2**d)==0:
        if 2**d!=a and r//(2**d)!=a and r//(2**d)!=2**d and 2**d!=r:
            l.append(2**d)
            l.append(r//2**d)

            n//=2**d
            d+=1
            break

        else:
            d+=1


    for i in range(3,k,2):
        d=1
        while n%(i**d)==0:
            if i**d!=a and r//(i**d)!=a and r//(i**d)!=i**d and i**d!=n:
                l.append(i**d)

                l.append(r//i**d)
                n//=i**d
                d+=1
                break
            else:
                d+=1

    return l

def factors(n):

    l=[]
    r=n
    k=int(math.sqrt(n))+1

    d=1
    while n%2==0:
        l.append(2**d)
        d+=1

        n//=2

    for i in range(3,k,2):
        d=1
        while n%i==0:
            l.append(i**d)
            d+=1

            n//=i

    if n==1:
        return l
    else:
        l.append(n)
        return l

