def string(s,n):
    j=''
    for i in range(n//4):
        if s[i]=='0' :
            j=j+'0000'
        elif s[i]=='1' :
            j=j+'0001'
        elif s[i]=='2' :
            j=j+'0010' 
        elif s[i]=='3' :
            j=j+'0011' 
        elif s[i]=='4' :
            j=j+'0100' 
        elif s[i]=='5' :
            j=j+'0101'
        elif s[i]=='6' :
            j=j+'0110'
        elif s[i]=='7' :
            j=j+'0111'
        elif s[i]=='8' :
            j=j+'1000'
        elif s[i]=='9' :
            j=j+'1001'
        elif s[i]=='A' :
            j=j+'1010'
        elif s[i]=='B' :
            j=j+'1011'
        elif s[i]=='C' :
            j=j+'1100'
        elif s[i]=='D' :
            j=j+'1101'
        elif s[i]=='E' :
            j=j+'1110'
        elif s[i]=='F' :
            j=j+'1111'


    return j                                        

